import{_ as a,c as t,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Privacy Choices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy-choices.md","filePath":"guide/privacy-choices.md","lastUpdated":1784988047000}'),s={name:"guide/privacy-choices.md"};function r(n,e,l,c,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-choices" tabindex="-1">Privacy Choices <a class="header-anchor" href="#privacy-choices" aria-label="Permalink to &quot;Privacy Choices&quot;">​</a></h1><p>Minesweeper is an offline-first app that does not collect, transmit, or store any personal data on external servers. This page explains your privacy options.</p><h2 id="your-data-stays-on-your-device" tabindex="-1">Your Data Stays on Your Device <a class="header-anchor" href="#your-data-stays-on-your-device" aria-label="Permalink to &quot;Your Data Stays on Your Device&quot;">​</a></h2><ul><li>All game data — settings, game state, and statistics — is stored locally on your device.</li><li>Nothing is uploaded, transmitted, or shared with anyone.</li><li>There are no accounts, no cloud sync, and no data collection.</li></ul><h2 id="the-only-network-feature-more-apps" tabindex="-1">The Only Network Feature: &quot;More Apps&quot; <a class="header-anchor" href="#the-only-network-feature-more-apps" aria-label="Permalink to &quot;The Only Network Feature: &quot;More Apps&quot;&quot;">​</a></h2><p>The only network access in Minesweeper is the optional <strong>&quot;More Apps&quot;</strong> section in Settings, which fetches a list of sibling apps. This feature:</p><ul><li>Sends no personal data — it only retrieves a list of app names and links.</li><li>Can be ignored entirely with no impact on gameplay.</li><li>Does not track you or store any identifiers.</li></ul><h2 id="clearing-your-data" tabindex="-1">Clearing Your Data <a class="header-anchor" href="#clearing-your-data" aria-label="Permalink to &quot;Clearing Your Data&quot;">​</a></h2><p>To remove all app data from your device:</p><ul><li><strong>iPhone/iPad</strong>: Delete and reinstall the app</li><li><strong>Mac</strong>: Quit Minesweeper, then remove the container:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.minesweeper</span></span></code></pre></div><p>This will permanently delete all settings and game data.</p><h2 id="no-tracking-no-ads" tabindex="-1">No Tracking, No Ads <a class="header-anchor" href="#no-tracking-no-ads" aria-label="Permalink to &quot;No Tracking, No Ads&quot;">​</a></h2><p>Minesweeper contains no advertising, no analytics, no tracking pixels, and no third-party data-sharing integrations. The app does not require network access for gameplay.</p><h2 id="privacy-requests" tabindex="-1">Privacy Requests <a class="header-anchor" href="#privacy-requests" aria-label="Permalink to &quot;Privacy Requests&quot;">​</a></h2><p>Since no personal data is collected or transmitted, there is no server-side data to access, delete, or port. If you have questions, open an issue at <code>https://github.com/minesweeper-app/minesweeper-site/issues</code>.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>If you have questions about this process, open an issue at <code>https://github.com/minesweeper-app/minesweeper-site/issues</code>.</p>',18)])])}const y=a(s,[["render",r]]);export{u as __pageData,y as default};
